-- 0161: Hunter x Hunter — Korrektur der Korrektur 0158: Die Dowsing Chain sitzt am
-- RINGFINGER (導く薬指の鎖); am Zeigefinger sitzt die Steal Chain. Idempotent.
update question_translations set explanation = 'Lies, on the other hand, are detected by the Dowsing Chain on his ring finger.' where lang = 'en' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was bewirkt Kurapikas „Holy Chain“?');
update question_translations set explanation = 'Las mentiras, en cambio, las detecta la Dowsing Chain de su dedo anular.' where lang = 'es' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was bewirkt Kurapikas „Holy Chain“?');
update question_translations set explanation = 'Les mensonges, eux, sont détectés par la Dowsing Chain de son annulaire.' where lang = 'fr' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was bewirkt Kurapikas „Holy Chain“?');
update question_translations set explanation = 'Já as mentiras são detectadas pela Dowsing Chain do dedo anelar dele.' where lang = 'pt' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was bewirkt Kurapikas „Holy Chain“?');
update question_translations set explanation = 'Le bugie, invece, le rileva la Dowsing Chain del suo anulare.' where lang = 'it' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was bewirkt Kurapikas „Holy Chain“?');
update question_translations set explanation = 'Sebaliknya, kebohongan dideteksi oleh Dowsing Chain di jari manisnya.' where lang = 'id' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was bewirkt Kurapikas „Holy Chain“?');
update question_translations set explanation = 'Yalanları ise yüzük parmağındaki Dowsing Chain tespit eder.' where lang = 'tr' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was bewirkt Kurapikas „Holy Chain“?');
update question_translations set explanation = 'Kłamstwa wykrywa natomiast Dowsing Chain na jego palcu serdecznym.' where lang = 'pl' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was bewirkt Kurapikas „Holy Chain“?');
update question_translations set explanation = 'Còn lời nói dối thì do Dowsing Chain ở ngón áp út phát hiện.' where lang = 'vi' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was bewirkt Kurapikas „Holy Chain“?');
update question_translations set explanation = 'Lügen erkennt dagegen die „Dowsing Chain“ an seinem Ringfinger.' where lang = 'de' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was bewirkt Kurapikas „Holy Chain“?');
